def think(thought="", **_extra):
    import json, os, datetime, time, uuid

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0340000" if __import__("os").path.isdir("./environment_mix/0340000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    def _now_iso():
        return datetime.datetime.now(datetime.timezone.utc).isoformat()

    def _parse_dt(s):
        if not s:
            return None
        if isinstance(s, datetime.datetime):
            return s if s.tzinfo else s.replace(tzinfo=datetime.timezone.utc)
        if not isinstance(s, str):
            return None
        try:
            # handle trailing Z
            if s.endswith("Z"):
                s = s[:-1] + "+00:00"
            dt = datetime.datetime.fromisoformat(s)
            return dt if dt.tzinfo else dt.replace(tzinfo=datetime.timezone.utc)
        except Exception:
            return None

    def _day_key_utc(dt):
        dt = dt.astimezone(datetime.timezone.utc)
        return dt.date().isoformat()

    def _audit(endpoint, api_key_id, session_id, status, latency_ms, error_code=None):
        events = _load("session_events.json")
        now = _now_iso()
        events.append({
            "id": f"sev_{uuid.uuid4().hex}",
            "session_id": session_id,
            "event_type": "session_created" if False else "think_appended",  # overwritten by caller if needed; kept to satisfy schema enum
            "event_payload": {
                "_audit": True,
                "endpoint": endpoint,
                "api_key_id": api_key_id,
                "status": status,
                "latency_ms": latency_ms,
                "error_code": error_code,
                "timestamp": now
            },
            "created_at": now,
            "updated_at": now
        })
        _save("session_events.json", events)

    t0 = time.time()

    # Validate input
    if thought is None:
        thought = ""
    if not isinstance(thought, str):
        # try to audit with best-effort context resolution
        api_keys = _load("api_keys.json")
        sessions = _load("sessions.json")
        active_keys = [k for k in api_keys if k.get("status") == "active"]
        sess = None
        key = None
        for k in active_keys:
            for s in sessions:
                if s.get("api_key_id") == k.get("id") and s.get("status") in ("active", "cleared"):
                    key = k
                    sess = s
                    break
            if sess:
                break
        if key and sess:
            _audit("think", key.get("id"), sess.get("id"), "error", int((time.time() - t0) * 1000), error_code="VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "`thought` must be a string.")
    if len(thought) > 50000:
        api_keys = _load("api_keys.json")
        sessions = _load("sessions.json")
        active_keys = [k for k in api_keys if k.get("status") == "active"]
        sess = None
        key = None
        for k in active_keys:
            for s in sessions:
                if s.get("api_key_id") == k.get("id") and s.get("status") in ("active", "cleared"):
                    key = k
                    sess = s
                    break
            if sess:
                break
        if key and sess:
            _audit("think", key.get("id"), sess.get("id"), "error", int((time.time() - t0) * 1000), error_code="VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "Thought exceeds maximum length of 50000 characters.", limit=50000)

    # Resolve ambient auth context: pick a working active api_key + active/cleared session.
    api_keys = _load("api_keys.json")
    sessions = _load("sessions.json")
    thoughts = _load("thoughts.json")
    session_events = _load("session_events.json")

    now_dt = datetime.datetime.now(datetime.timezone.utc)
    now_iso = now_dt.isoformat()

    def _rate_limited_for_key(key_id, rps):
        if not rps or rps <= 0:
            return False
        window_s = 1.0
        since = now_dt - datetime.timedelta(seconds=window_s)
        cnt = 0
        for ev in session_events:
            payload = (ev.get("event_payload") or {})
            if not (isinstance(payload, dict) and payload.get("_audit") is True):
                continue
            if payload.get("api_key_id") != key_id:
                continue
            ts = _parse_dt(payload.get("timestamp"))
            if ts and ts >= since:
                cnt += 1
        return cnt >= float(rps)

    def _today_thought_writes(key_id):
        day = _day_key_utc(now_dt)
        cnt = 0
        for ev in session_events:
            if ev.get("event_type") != "think_appended":
                continue
            payload = ev.get("event_payload") or {}
            if not isinstance(payload, dict):
                continue
            if payload.get("api_key_id") != key_id:
                continue
            ts = _parse_dt(ev.get("created_at"))
            if ts and _day_key_utc(ts) == day:
                cnt += 1
        return cnt

    chosen_key = None
    chosen_session = None

    active_keys = [k for k in api_keys if k.get("status") == "active"]
    # Prefer a session with status active/cleared; if multiple, pick most recently updated.
    for k in active_keys:
        # Rate limit check for candidate key
        rps = k.get("rate_limit_rps")
        try:
            rps_val = float(rps)
        except Exception:
            rps_val = None

        # Need at least one eligible session
        eligible = [s for s in sessions if s.get("api_key_id") == k.get("id") and s.get("status") in ("active", "cleared")]
        # Exclude expired by expires_at when set
        filtered = []
        for s in eligible:
            exp = _parse_dt(s.get("expires_at"))
            if exp is not None and exp <= now_dt:
                continue
            filtered.append(s)
        eligible = filtered

        if not eligible:
            continue

        # Pick latest updated_at
        eligible.sort(key=lambda s: (_parse_dt(s.get("updated_at")) or datetime.datetime.min.replace(tzinfo=datetime.timezone.utc)), reverse=True)
        s = eligible[0]

        # Ensure rate limiting can be satisfied; if violated, try another key
        if rps_val is not None and _rate_limited_for_key(k.get("id"), rps_val):
            continue

        chosen_key = k
        chosen_session = s
        break

    if not chosen_key or not chosen_session:
        # audit cannot be recorded without a session_id per schema FK; return UNAUTHORIZED
        return _err("UNAUTHORIZED", "No authenticated session context available.")

    api_key_id = chosen_key.get("id")
    session_id = chosen_session.get("id")

    # Enforce api key active
    if chosen_key.get("status") != "active":
        # audit attempt
        _audit("think", api_key_id, session_id, "error", int((time.time() - t0) * 1000), error_code="UNAUTHORIZED")
        return _err("UNAUTHORIZED", "API key is not active.")

    # Enforce rate limit for the chosen key (now that context is selected)
    try:
        rps_val = float(chosen_key.get("rate_limit_rps"))
    except Exception:
        rps_val = None
    if rps_val is not None and rps_val > 0 and _rate_limited_for_key(api_key_id, rps_val):
        _audit("think", api_key_id, session_id, "error", int((time.time() - t0) * 1000), error_code="RATE_LIMIT")
        return _err("RATE_LIMIT", "Rate limit exceeded.", rate_limit_rps=rps_val)

    # Enforce daily quota (if > 0)
    daily_limit = chosen_key.get("daily_thought_limit")
    if not isinstance(daily_limit, int):
        # schema says integer; treat invalid as server misconfig -> validation-like error
        _audit("think", api_key_id, session_id, "error", int((time.time() - t0) * 1000), error_code="VALIDATION_ERROR")
        return _err("VALIDATION_ERROR", "API key daily_thought_limit is invalid.")
    if daily_limit > 0:
        used = _today_thought_writes(api_key_id)
        if used >= daily_limit:
            _audit("think", api_key_id, session_id, "error", int((time.time() - t0) * 1000), error_code="QUOTA_EXCEEDED")
            return _err("QUOTA_EXCEEDED", "Daily thought limit exceeded.", daily_thought_limit=daily_limit, used_today=used)

    # Session state must allow appends (active or cleared); if cleared, allow and set back to active
    if chosen_session.get("status") not in ("active", "cleared"):
        _audit("think", api_key_id, session_id, "error", int((time.time() - t0) * 1000), error_code="CONFLICT")
        return _err("CONFLICT", "Session is not in a state that allows appending thoughts.", session_status=chosen_session.get("status"))

    # Compute next sequence_no within session
    max_seq = 0
    for th in thoughts:
        if th.get("session_id") == session_id:
            try:
                seq = int(th.get("sequence_no"))
            except Exception:
                continue
            if seq > max_seq:
                max_seq = seq
    next_seq = max_seq + 1

    # Create thought row
    thought_id = f"th_{uuid.uuid4().hex}"
    char_len = len(thought)
    new_thought = {
        "id": thought_id,
        "session_id": session_id,
        "sequence_no": next_seq,
        "thought": thought,
        "status": "active",
        "char_len": char_len,
        "token_estimate": None,
        "purged_at": None,
        "created_at": now_iso,
        "updated_at": now_iso
    }

    # Mutate session: status to active if was cleared; update thought_count and last_thought_at
    # Maintain invariant: thought_count equals active thoughts count
    active_count = 0
    for th in thoughts:
        if th.get("session_id") == session_id and th.get("status") == "active":
            active_count += 1
    new_active_count = active_count + 1

    for s in sessions:
        if s.get("id") == session_id:
            # transition cleared->active is allowed; active->active ok
            if s.get("status") == "cleared":
                s["status"] = "active"
            s["thought_count"] = new_active_count
            s["last_thought_at"] = now_iso
            s["updated_at"] = now_iso
            break

    # Append thought and session event
    thoughts.append(new_thought)
    ev_id = f"sev_{uuid.uuid4().hex}"
    session_events.append({
        "id": ev_id,
        "session_id": session_id,
        "event_type": "think_appended",
        "event_payload": {"api_key_id": api_key_id, "thought_id": thought_id, "char_len": char_len, "sequence_no": next_seq},
        "created_at": now_iso,
        "updated_at": now_iso
    })

    # Audit row (as an additional session_events entry, stored as think_appended to satisfy enum)
    latency_ms = int((time.time() - t0) * 1000)
    session_events.append({
        "id": f"sev_{uuid.uuid4().hex}",
        "session_id": session_id,
        "event_type": "think_appended",
        "event_payload": {
            "_audit": True,
            "endpoint": "think",
            "api_key_id": api_key_id,
            "status": "ok",
            "latency_ms": latency_ms,
            "timestamp": now_iso
        },
        "created_at": now_iso,
        "updated_at": now_iso
    })

    _save("thoughts.json", thoughts)
    _save("sessions.json", sessions)
    _save("session_events.json", session_events)

    return {
        "thought": new_thought,
        "session": {"id": session_id, "thought_count": new_active_count, "status": next(s.get("status") for s in sessions if s.get("id") == session_id)},
        "meta": {"latency_ms": latency_ms}
    }

def get_thoughts(status=None, limit=None, cursor=None, sort=None, order=None, **_extra):
    import json, os, datetime, time, uuid, hashlib, base64

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0340000" if __import__("os").path.isdir("./environment_mix/0340000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    started = time.time()

    def _now_z():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _ensure_request_log():
        path = os.path.join(_DB, "request_logs.json")
        if not os.path.exists(path):
            _save("request_logs.json", [])
        return "request_logs.json"

    def _log(endpoint, api_key_id, session_id, http_status):
        # Logging must not break the API call.
        try:
            logs = _load(_ensure_request_log())
            if not isinstance(logs, list):
                logs = []
            latency_ms = int(max(0.0, (time.time() - started) * 1000.0))
            logs.append({
                "id": "req_" + uuid.uuid4().hex,
                "endpoint": endpoint,
                "api_key_id": api_key_id,
                "session_id": session_id,
                "status": http_status,
                "latency_ms": latency_ms,
                "created_at": _now_z()
            })
            _save("request_logs.json", logs)
        except Exception:
            pass

    def _parse_dt(s):
        if s is None:
            return None
        if isinstance(s, datetime.datetime):
            return s
        if not isinstance(s, str):
            return None
        try:
            if s.endswith("Z"):
                s = s[:-1] + "+00:00"
            return datetime.datetime.fromisoformat(s)
        except Exception:
            return None

    def _rate_limit_check(api_key_row):
        rps = api_key_row.get("rate_limit_rps")
        if not isinstance(rps, (int, float)) or rps <= 0:
            return True
        logs = _load(_ensure_request_log())
        if not isinstance(logs, list):
            return True
        now = datetime.datetime.utcnow()
        cutoff = now - datetime.timedelta(seconds=1)
        c = 0
        for r in logs:
            if not isinstance(r, dict):
                continue
            if r.get("api_key_id") != api_key_row.get("id"):
                continue
            ts = _parse_dt(r.get("created_at"))
            if ts is None:
                continue
            if ts >= cutoff:
                c += 1
        # This request counts too; reject if it would exceed.
        return (c + 1) <= float(rps) + 1e-9

    def _resolve_context():
        # Ambient auth: pick any active api_key with a usable session, preferring:
        # - active session
        # - else cleared session
        # - else any session (for reads)
        api_keys = _load("api_keys.json")
        sessions = _load("sessions.json")
        if not isinstance(api_keys, list):
            api_keys = []
        if not isinstance(sessions, list):
            sessions = []

        candidates = []
        for k in api_keys:
            if not isinstance(k, dict):
                continue
            if k.get("status") != "active":
                continue
            kid = k.get("id")
            if not isinstance(kid, str) or not kid:
                continue
            sess_for_key = [s for s in sessions if isinstance(s, dict) and s.get("api_key_id") == kid]
            if not sess_for_key:
                continue

            def _rank(s):
                st = s.get("status")
                # reads should prefer active > cleared > others
                if st == "active":
                    return 0
                if st == "cleared":
                    return 1
                if st == "expired":
                    return 2
                if st == "closed":
                    return 3
                return 4

            sess_for_key.sort(key=_rank)
            candidates.append((k, sess_for_key[0]))

        if not candidates:
            return None, None

        # Prefer a key that passes rate limit, but don't brick if none do (then we rate-limit).
        for k, s in candidates:
            if _rate_limit_check(k):
                return k, s
        # return first to let caller produce RATE_LIMIT error
        return candidates[0][0], candidates[0][1]

    # ---- validate inputs (but do not validate cursor against a strict format; it's opaque)
    if status is not None and status not in ("active", "purged"):
        api_key_row, session_row = _resolve_context()
        _log("get_thoughts", api_key_row.get("id") if api_key_row else None, session_row.get("id") if session_row else None, 400)
        return _err("VALIDATION_ERROR", "Invalid status; must be 'active' or 'purged'.")

    if limit is None:
        limit = 50
    if not isinstance(limit, int):
        api_key_row, session_row = _resolve_context()
        _log("get_thoughts", api_key_row.get("id") if api_key_row else None, session_row.get("id") if session_row else None, 400)
        return _err("VALIDATION_ERROR", "Invalid limit; must be an integer.")
    if limit < 1 or limit > 200:
        api_key_row, session_row = _resolve_context()
        _log("get_thoughts", api_key_row.get("id") if api_key_row else None, session_row.get("id") if session_row else None, 400)
        return _err("VALIDATION_ERROR", "Invalid limit; must be between 1 and 200.")

    if sort is None:
        sort = "sequence_no"
    if sort not in ("sequence_no", "created_at"):
        api_key_row, session_row = _resolve_context()
        _log("get_thoughts", api_key_row.get("id") if api_key_row else None, session_row.get("id") if session_row else None, 400)
        return _err("VALIDATION_ERROR", "Unsupported sort; must be 'sequence_no' or 'created_at'.")

    if order is None:
        order = "asc"
    if order not in ("asc", "desc"):
        api_key_row, session_row = _resolve_context()
        _log("get_thoughts", api_key_row.get("id") if api_key_row else None, session_row.get("id") if session_row else None, 400)
        return _err("VALIDATION_ERROR", "Unsupported order; must be 'asc' or 'desc'.")

    if cursor is not None and not isinstance(cursor, str):
        api_key_row, session_row = _resolve_context()
        _log("get_thoughts", api_key_row.get("id") if api_key_row else None, session_row.get("id") if session_row else None, 400)
        return _err("VALIDATION_ERROR", "Invalid cursor; must be a string.")
    if cursor is not None and cursor.strip() == "":
        cursor = None

    api_key_row, session_row = _resolve_context()
    if api_key_row is None or session_row is None:
        _log("get_thoughts", None, None, 401)
        return _err("UNAUTHORIZED", "No authenticated context with an active API key and an existing session was found.")

    if not _rate_limit_check(api_key_row):
        _log("get_thoughts", api_key_row.get("id"), session_row.get("id"), 429)
        return _err("RATE_LIMIT", "Rate limit exceeded for this API key.")

    thoughts = _load("thoughts.json")
    if not isinstance(thoughts, list):
        thoughts = []

    sess_id = session_row.get("id")

    filt_status = status if status is not None else "active"
    rows = [t for t in thoughts if isinstance(t, dict) and t.get("session_id") == sess_id and t.get("status") == filt_status]

    def _sort_key(t):
        if sort == "sequence_no":
            v = t.get("sequence_no")
            return (v if isinstance(v, int) else 0, t.get("id") or "")
        # created_at
        dt = _parse_dt(t.get("created_at"))
        # Ensure stable ordering
        return (dt if dt is not None else datetime.datetime.fromtimestamp(0, tz=datetime.timezone.utc), t.get("id") or "")

    reverse = (order == "desc")
    rows.sort(key=_sort_key, reverse=reverse)

    # Cursor is opaque; implement as a stable index token bound to this session+filter+sort+order snapshot key.
    # Accept any cursor format; only error if it *looks like ours* but fails to decode/validate.
    start_idx = 0
    if cursor is not None:
        if cursor.startswith("ttk_cur_"):
            token = cursor[len("ttk_cur_"):]
            try:
                raw = base64.urlsafe_b64decode(token.encode("utf-8") + b"===")
                payload = raw.decode("utf-8")
                parts = payload.split("|")
                if len(parts) != 3:
                    _log("get_thoughts", api_key_row.get("id"), sess_id, 400)
                    return _err("VALIDATION_ERROR", "Invalid cursor.")
                sig, idx_s, sid = parts
                if sid != sess_id:
                    _log("get_thoughts", api_key_row.get("id"), sess_id, 400)
                    return _err("VALIDATION_ERROR", "Invalid cursor.")
                try:
                    idx = int(idx_s)
                except Exception:
                    _log("get_thoughts", api_key_row.get("id"), sess_id, 400)
                    return _err("VALIDATION_ERROR", "Invalid cursor.")
                expected_sig = hashlib.sha256((sess_id + "|" + filt_status + "|" + sort + "|" + order).encode("utf-8")).hexdigest()[:16]
                if sig != expected_sig or idx < 0:
                    _log("get_thoughts", api_key_row.get("id"), sess_id, 400)
                    return _err("VALIDATION_ERROR", "Invalid cursor.")
                start_idx = min(idx, len(rows))
            except Exception:
                _log("get_thoughts", api_key_row.get("id"), sess_id, 400)
                return _err("VALIDATION_ERROR", "Invalid cursor.")
        else:
            # For compatibility, treat unknown opaque cursors as "start from beginning" rather than erroring.
            # This relaxes validation to match the tool's opaque cursor contract.
            start_idx = 0

    page = rows[start_idx:start_idx + limit]
    next_cursor = None
    if start_idx + limit < len(rows):
        sig = hashlib.sha256((sess_id + "|" + filt_status + "|" + sort + "|" + order).encode("utf-8")).hexdigest()[:16]
        payload = f"{sig}|{start_idx + limit}|{sess_id}".encode("utf-8")
        token = base64.urlsafe_b64encode(payload).decode("utf-8").rstrip("=")
        next_cursor = "ttk_cur_" + token

    _log("get_thoughts", api_key_row.get("id"), sess_id, 200)
    return {
        "data": page,
        "meta": {
            "total": len(rows),
            "limit": limit,
            "has_more": (next_cursor is not None),
            "next_cursor": next_cursor,
            "status": filt_status,
            "sort": sort,
            "order": order,
            "session_id": sess_id
        }
    }

def clear_thoughts(purge=True, reason=None, **_extra):
    import json, os, datetime, time, uuid

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0340000" if __import__("os").path.isdir("./environment_mix/0340000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    def _now_iso():
        return datetime.datetime.now(datetime.timezone.utc).isoformat()

    def _parse_dt(s):
        if not s:
            return None
        if isinstance(s, datetime.datetime):
            return s if s.tzinfo else s.replace(tzinfo=datetime.timezone.utc)
        if not isinstance(s, str):
            return None
        try:
            if s.endswith("Z"):
                s = s[:-1] + "+00:00"
            dt = datetime.datetime.fromisoformat(s)
            return dt if dt.tzinfo else dt.replace(tzinfo=datetime.timezone.utc)
        except Exception:
            return None

    t0 = time.time()
    now_iso = _now_iso()
    now_dt = datetime.datetime.now(datetime.timezone.utc)

    # Validate inputs
    if purge is None:
        purge = True
    if not isinstance(purge, bool):
        return _err("VALIDATION_ERROR", "`purge` must be a boolean.")
    if reason is not None and not isinstance(reason, str):
        return _err("VALIDATION_ERROR", "`reason` must be a string when provided.")
    if isinstance(reason, str) and len(reason) > 10000:
        return _err("VALIDATION_ERROR", "`reason` is too long.", maximum=10000)

    api_keys = _load("api_keys.json")
    sessions = _load("sessions.json")
    thoughts = _load("thoughts.json")
    session_events = _load("session_events.json")

    def _rate_limited_for_key(key_id, rps):
        if not rps or rps <= 0:
            return False
        since = now_dt - datetime.timedelta(seconds=1)
        cnt = 0
        for ev in session_events:
            payload = (ev.get("event_payload") or {})
            if not (isinstance(payload, dict) and payload.get("_audit") is True):
                continue
            if payload.get("api_key_id") != key_id:
                continue
            ts = _parse_dt(payload.get("timestamp"))
            if ts and ts >= since:
                cnt += 1
        return cnt >= float(rps)

    chosen_key = None
    chosen_session = None
    active_keys = [k for k in api_keys if k.get("status") == "active"]
    for k in active_keys:
        eligible = [s for s in sessions if s.get("api_key_id") == k.get("id") and s.get("status") in ("active", "cleared")]
        tmp = []
        for s in eligible:
            exp = _parse_dt(s.get("expires_at"))
            if exp is not None and exp <= now_dt:
                continue
            tmp.append(s)
        eligible = tmp
        if not eligible:
            continue
        try:
            rps_val = float(k.get("rate_limit_rps"))
        except Exception:
            rps_val = None
        if rps_val is not None and _rate_limited_for_key(k.get("id"), rps_val):
            continue
        eligible.sort(key=lambda s: (_parse_dt(s.get("updated_at")) or datetime.datetime.min.replace(tzinfo=datetime.timezone.utc)), reverse=True)
        chosen_key = k
        chosen_session = eligible[0]
        break

    if not chosen_key or not chosen_session:
        return _err("UNAUTHORIZED", "No authenticated session context available.")

    api_key_id = chosen_key.get("id")
    session_id = chosen_session.get("id")

    # Rate limit
    try:
        rps_val = float(chosen_key.get("rate_limit_rps"))
    except Exception:
        rps_val = None
    if rps_val is not None and rps_val > 0 and _rate_limited_for_key(api_key_id, rps_val):
        latency_ms = int((time.time() - t0) * 1000)
        session_events.append({
            "id": f"sev_{uuid.uuid4().hex}",
            "session_id": session_id,
            "event_type": "think_appended",
            "event_payload": {"_audit": True, "endpoint": "clear_thoughts", "api_key_id": api_key_id, "status": "error",
                              "latency_ms": latency_ms, "error_code": "RATE_LIMIT", "timestamp": now_iso},
            "created_at": now_iso,
            "updated_at": now_iso
        })
        _save("session_events.json", session_events)
        return _err("RATE_LIMIT", "Rate limit exceeded.", rate_limit_rps=rps_val)

    # Session state must allow transition to cleared: only active or cleared per lifecycle
    cur_status = chosen_session.get("status")
    if cur_status not in ("active", "cleared"):
        latency_ms = int((time.time() - t0) * 1000)
        session_events.append({
            "id": f"sev_{uuid.uuid4().hex}",
            "session_id": session_id,
            "event_type": "think_appended",
            "event_payload": {"_audit": True, "endpoint": "clear_thoughts", "api_key_id": api_key_id, "status": "error",
                              "latency_ms": latency_ms, "error_code": "CONFLICT", "timestamp": now_iso},
            "created_at": now_iso,
            "updated_at": now_iso
        })
        _save("session_events.json", session_events)
        return _err("CONFLICT", "Session is not in a state that allows clearing thoughts.", session_status=cur_status)

    # Perform purge if requested; always set session cleared_at/status/thought_count per rule
    number_purged = 0
    if purge:
        for th in thoughts:
            if th.get("session_id") == session_id and th.get("status") == "active":
                th["status"] = "purged"
                th["purged_at"] = now_iso
                th["updated_at"] = now_iso
                number_purged += 1

    # Update session
    for s in sessions:
        if s.get("id") == session_id:
            # active->cleared allowed; cleared->cleared allowed as idempotent "clear" semantic
            s["status"] = "cleared"
            s["cleared_at"] = now_iso
            s["thought_count"] = 0
            s["updated_at"] = now_iso
            break

    # Insert session event for clear (always)
    payload = {"api_key_id": api_key_id, "number_purged": number_purged, "purge": purge}
    if reason is not None:
        payload["reason"] = reason
    session_events.append({
        "id": f"sev_{uuid.uuid4().hex}",
        "session_id": session_id,
        "event_type": "thoughts_cleared",
        "event_payload": payload,
        "created_at": now_iso,
        "updated_at": now_iso
    })

    latency_ms = int((time.time() - t0) * 1000)
    session_events.append({
        "id": f"sev_{uuid.uuid4().hex}",
        "session_id": session_id,
        "event_type": "think_appended",
        "event_payload": {"_audit": True, "endpoint": "clear_thoughts", "api_key_id": api_key_id, "status": "ok",
                          "latency_ms": latency_ms, "timestamp": now_iso},
        "created_at": now_iso,
        "updated_at": now_iso
    })

    _save("thoughts.json", thoughts)
    _save("sessions.json", sessions)
    _save("session_events.json", session_events)

    return {
        "session_id": session_id,
        "purge": purge,
        "number_purged": number_purged,
        "session": {"id": session_id, "status": "cleared", "thought_count": 0, "cleared_at": now_iso},
        "meta": {"latency_ms": latency_ms}
    }

def get_thought_stats(include_purged=False, **_extra):
    import json, os, datetime, time, uuid

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0340000" if __import__("os").path.isdir("./environment_mix/0340000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    def _now_iso():
        return datetime.datetime.now(datetime.timezone.utc).isoformat()

    def _parse_dt(s):
        if not s:
            return None
        if isinstance(s, datetime.datetime):
            return s if s.tzinfo else s.replace(tzinfo=datetime.timezone.utc)
        if not isinstance(s, str):
            return None
        try:
            if s.endswith("Z"):
                s = s[:-1] + "+00:00"
            dt = datetime.datetime.fromisoformat(s)
            return dt if dt.tzinfo else dt.replace(tzinfo=datetime.timezone.utc)
        except Exception:
            return None

    t0 = time.time()
    now_iso = _now_iso()
    now_dt = datetime.datetime.now(datetime.timezone.utc)

    if include_purged is None:
        include_purged = False
    if not isinstance(include_purged, bool):
        return _err("VALIDATION_ERROR", "`include_purged` must be a boolean.")

    api_keys = _load("api_keys.json")
    sessions = _load("sessions.json")
    thoughts = _load("thoughts.json")
    session_events = _load("session_events.json")

    def _rate_limited_for_key(key_id, rps):
        if not rps or rps <= 0:
            return False
        since = now_dt - datetime.timedelta(seconds=1)
        cnt = 0
        for ev in session_events:
            payload = (ev.get("event_payload") or {})
            if not (isinstance(payload, dict) and payload.get("_audit") is True):
                continue
            if payload.get("api_key_id") != key_id:
                continue
            ts = _parse_dt(payload.get("timestamp"))
            if ts and ts >= since:
                cnt += 1
        return cnt >= float(rps)

    # Resolve ambient session context
    chosen_key = None
    chosen_session = None
    active_keys = [k for k in api_keys if k.get("status") == "active"]
    for k in active_keys:
        eligible = [s for s in sessions if s.get("api_key_id") == k.get("id") and s.get("status") in ("active", "cleared")]
        tmp = []
        for s in eligible:
            exp = _parse_dt(s.get("expires_at"))
            if exp is not None and exp <= now_dt:
                continue
            tmp.append(s)
        eligible = tmp
        if not eligible:
            continue
        try:
            rps_val = float(k.get("rate_limit_rps"))
        except Exception:
            rps_val = None
        if rps_val is not None and _rate_limited_for_key(k.get("id"), rps_val):
            continue
        eligible.sort(key=lambda s: (_parse_dt(s.get("updated_at")) or datetime.datetime.min.replace(tzinfo=datetime.timezone.utc)), reverse=True)
        chosen_key = k
        chosen_session = eligible[0]
        break

    if not chosen_key or not chosen_session:
        return _err("UNAUTHORIZED", "No authenticated session context available.")

    api_key_id = chosen_key.get("id")
    session_id = chosen_session.get("id")

    # Ensure session exists (NOT_FOUND if referenced session is missing for caller)
    if not any(s.get("id") == session_id and s.get("api_key_id") == api_key_id for s in sessions):
        return _err("NOT_FOUND", "Session not found.")

    # Rate limit enforcement
    try:
        rps_val = float(chosen_key.get("rate_limit_rps"))
    except Exception:
        rps_val = None
    if rps_val is not None and rps_val > 0 and _rate_limited_for_key(api_key_id, rps_val):
        latency_ms = int((time.time() - t0) * 1000)
        session_events.append({
            "id": f"sev_{uuid.uuid4().hex}",
            "session_id": session_id,
            "event_type": "think_appended",
            "event_payload": {"_audit": True, "endpoint": "get_thought_stats", "api_key_id": api_key_id, "status": "error",
                              "latency_ms": latency_ms, "error_code": "RATE_LIMIT", "timestamp": now_iso},
            "created_at": now_iso,
            "updated_at": now_iso
        })
        _save("session_events.json", session_events)
        return _err("RATE_LIMIT", "Rate limit exceeded.", rate_limit_rps=rps_val)

    # Compute stats
    considered = []
    for th in thoughts:
        if th.get("session_id") != session_id:
            continue
        st = th.get("status")
        if include_purged:
            if st not in ("active", "purged"):
                continue
        else:
            if st != "active":
                continue
        considered.append(th)

    total = len(considered)
    total_chars = 0
    created_times = []
    for th in considered:
        try:
            total_chars += int(th.get("char_len") or 0)
        except Exception:
            total_chars += 0
        dt = _parse_dt(th.get("created_at"))
        if dt:
            created_times.append(dt)

    first_thought_at = min(created_times).isoformat() if created_times else None
    last_thought_at = max(created_times).isoformat() if created_times else None

    # Active-only stats required by business rules
    active_only = [th for th in thoughts if th.get("session_id") == session_id and th.get("status") == "active"]
    total_active = len(active_only)
    active_chars = 0
    active_times = []
    for th in active_only:
        try:
            active_chars += int(th.get("char_len") or 0)
        except Exception:
            pass
        dt = _parse_dt(th.get("created_at"))
        if dt:
            active_times.append(dt)

    first_active_at = min(active_times).isoformat() if active_times else None
    last_active_at = max(active_times).isoformat() if active_times else None

    # Reconcile cached thought_count invariant (write-through if mismatched)
    sessions_changed = False
    for s in sessions:
        if s.get("id") == session_id:
            if s.get("thought_count") != total_active:
                s["thought_count"] = total_active
                s["updated_at"] = now_iso
                sessions_changed = True
            break
    if sessions_changed:
        _save("sessions.json", sessions)

    latency_ms = int((time.time() - t0) * 1000)
    session_events.append({
        "id": f"sev_{uuid.uuid4().hex}",
        "session_id": session_id,
        "event_type": "think_appended",
        "event_payload": {"_audit": True, "endpoint": "get_thought_stats", "api_key_id": api_key_id, "status": "ok",
                          "latency_ms": latency_ms, "timestamp": now_iso},
        "created_at": now_iso,
        "updated_at": now_iso
    })
    _save("session_events.json", session_events)

    return {
        "session_id": session_id,
        "include_purged": include_purged,
        "stats": {
            "total_thoughts": total,
            "total_chars": total_chars,
            "first_thought_at": first_thought_at,
            "last_thought_at": last_thought_at,
            "total_active_thoughts": total_active,
            "active_total_chars": active_chars,
            "first_active_thought_at": first_active_at,
            "last_active_thought_at": last_active_at
        },
        "meta": {"latency_ms": latency_ms}
    }

def get_session(external_session_key=None, create_if_missing=None, **_extra):
    import json, os, datetime, time, uuid

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0340000" if __import__("os").path.isdir("./environment_mix/0340000") else "/app/database")

    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []

    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)

    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    def _now():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _ensure_request_log():
        path = os.path.join(_DB, "request_logs.json")
        if not os.path.exists(path):
            _save("request_logs.json", [])
        return "request_logs.json"

    def _log(endpoint, api_key_id, session_id, status, started):
        try:
            fname = _ensure_request_log()
            logs = _load(fname)
            if not isinstance(logs, list):
                logs = []
            latency_ms = int(max(0.0, (time.time() - started) * 1000.0))
            logs.append({
                "id": "req_" + uuid.uuid4().hex,
                "endpoint": endpoint,
                "api_key_id": api_key_id,
                "session_id": session_id,
                "status": status,
                "latency_ms": latency_ms,
                "created_at": _now()
            })
            _save(fname, logs)
        except Exception:
            pass

    def _validate():
        if external_session_key is not None:
            if not isinstance(external_session_key, str):
                return _err("VALIDATION_ERROR", "external_session_key must be a string.")
            if len(external_session_key) < 1 or len(external_session_key) > 256:
                return _err("VALIDATION_ERROR", "external_session_key length must be between 1 and 256.")
        if create_if_missing is not None and not isinstance(create_if_missing, bool):
            return _err("VALIDATION_ERROR", "create_if_missing must be a boolean.")
        return None

    started = time.time()
    v = _validate()
    if v:
        _log("get_session", None, None, "error", started)
        return v

    if create_if_missing is None:
        create_if_missing = True

    api_keys = _load("api_keys.json")
    sessions = _load("sessions.json")
    events = _load("session_events.json")
    thoughts = _load("thoughts.json")

    if not isinstance(api_keys, list) or not isinstance(sessions, list) or not isinstance(events, list) or not isinstance(thoughts, list):
        _log("get_session", None, None, "error", started)
        return _err("UNAUTHORIZED", "No valid API key/session context is available.")

    def _find_working_api_key():
        # Ambient auth: choose any key that can serve calls. Prefer active keys.
        for k in api_keys:
            try:
                if k.get("status") == "active":
                    return k
            except Exception:
                continue
        # If no active key, still choose any key to provide deterministic UNAUTHORIZED vs NOT_FOUND handling.
        return None

    key = _find_working_api_key()
    if not key:
        _log("get_session", None, None, "error", started)
        return _err("UNAUTHORIZED", "No valid API key/session context is available.")

    api_key_id = key.get("id")

    # Resolve session by (api_key_id, external_session_key) if provided
    def _session_matches(s):
        if s.get("api_key_id") != api_key_id:
            return False
        esk = s.get("external_session_key")
        if external_session_key is None:
            return esk is None
        return esk == external_session_key

    matching = [s for s in sessions if _session_matches(s)]

    # If multiple implicit sessions exist (shouldn't), pick the newest updated.
    def _dt(s, field):
        v = s.get(field)
        if not isinstance(v, str):
            return ""
        return v

    matching.sort(key=lambda s: _dt(s, "updated_at"), reverse=True)

    session = matching[0] if matching else None

    # If none exists and create_if_missing, create; otherwise NOT_FOUND
    if session is None:
        if not create_if_missing:
            _log("get_session", api_key_id, None, "not_found", started)
            return _err("NOT_FOUND", "Session not found.")
        # Enforce: for implicit sessions, allow at most one with status in ('active','cleared') per api_key
        if external_session_key is None:
            for s in sessions:
                if s.get("api_key_id") == api_key_id and s.get("external_session_key") is None and s.get("status") in ("active", "cleared"):
                    session = s
                    break

        if session is None:
            now = _now()
            session = {
                "id": "ses_" + uuid.uuid4().hex,
                "api_key_id": api_key_id,
                "external_session_key": external_session_key,
                "status": "active",
                "thought_count": 0,
                "last_thought_at": None,
                "cleared_at": None,
                "expires_at": None,
                "created_at": now,
                "updated_at": now
            }
            # Unique(api_key_id, external_session_key) where external_session_key not null
            if external_session_key is not None:
                for s in sessions:
                    if s.get("api_key_id") == api_key_id and s.get("external_session_key") == external_session_key:
                        _log("get_session", api_key_id, None, "conflict", started)
                        return _err("CONFLICT", "A session with this external_session_key already exists.")
            sessions.append(session)
            _save("sessions.json", sessions)

            ev = {
                "id": "sev_" + uuid.uuid4().hex,
                "session_id": session["id"],
                "event_type": "session_created",
                "event_payload": {"external_session_key": external_session_key},
                "created_at": now,
                "updated_at": now
            }
            events.append(ev)
            _save("session_events.json", events)

    # Session exists but must be resolvable: NOT_FOUND if referenced missing (here it's direct row)
    if not isinstance(session, dict) or not session.get("id"):
        _log("get_session", api_key_id, None, "not_found", started)
        return _err("NOT_FOUND", "Session not found.")

    # Reconcile thought_count invariant for this session
    sid = session["id"]
    active_thoughts = [t for t in thoughts if t.get("session_id") == sid and t.get("status") == "active"]
    real_count = len(active_thoughts)
    if session.get("thought_count") != real_count:
        session["thought_count"] = real_count
        session["updated_at"] = _now()
        # also refresh last_thought_at from active thoughts if mismatch and there are any
        if real_count > 0:
            # last_thought_at is for most recent appended; approximate with max(created_at) among active thoughts
            last_created = None
            for t in active_thoughts:
                ca = t.get("created_at")
                if isinstance(ca, str) and (last_created is None or ca > last_created):
                    last_created = ca
            session["last_thought_at"] = last_created
        _save("sessions.json", sessions)

    _log("get_session", api_key_id, sid, "ok", started)
    return {"session": session}

def close_session(external_session_key=None, reason=None, **_extra):
    import json, os, datetime, time, uuid

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0340000" if __import__("os").path.isdir("./environment_mix/0340000") else "/app/database")

    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []

    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)

    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    def _now():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _ensure_request_log():
        path = os.path.join(_DB, "request_logs.json")
        if not os.path.exists(path):
            _save("request_logs.json", [])
        return "request_logs.json"

    def _log(endpoint, api_key_id, session_id, status, started):
        try:
            fname = _ensure_request_log()
            logs = _load(fname)
            if not isinstance(logs, list):
                logs = []
            latency_ms = int(max(0.0, (time.time() - started) * 1000.0))
            logs.append({
                "id": "req_" + uuid.uuid4().hex,
                "endpoint": endpoint,
                "api_key_id": api_key_id,
                "session_id": session_id,
                "status": status,
                "latency_ms": latency_ms,
                "created_at": _now()
            })
            _save(fname, logs)
        except Exception:
            pass

    def _validate():
        if external_session_key is not None:
            if not isinstance(external_session_key, str):
                return _err("VALIDATION_ERROR", "external_session_key must be a string.")
            if len(external_session_key) < 1 or len(external_session_key) > 256:
                return _err("VALIDATION_ERROR", "external_session_key length must be between 1 and 256.")
        if reason is not None:
            if not isinstance(reason, str):
                return _err("VALIDATION_ERROR", "reason must be a string.")
            if len(reason) > 1024:
                return _err("VALIDATION_ERROR", "reason length must be <= 1024.")
        return None

    started = time.time()
    v = _validate()
    if v:
        _log("close_session", None, None, "error", started)
        return v

    api_keys = _load("api_keys.json")
    sessions = _load("sessions.json")
    events = _load("session_events.json")
    thoughts = _load("thoughts.json")

    if not isinstance(api_keys, list) or not isinstance(sessions, list) or not isinstance(events, list) or not isinstance(thoughts, list):
        _log("close_session", None, None, "error", started)
        return _err("UNAUTHORIZED", "No session/auth context is available.")

    key = None
    for k in api_keys:
        try:
            if k.get("status") == "active":
                key = k
                break
        except Exception:
            continue
    if not key:
        _log("close_session", None, None, "unauthorized", started)
        return _err("UNAUTHORIZED", "No session/auth context is available.")

    api_key_id = key.get("id")

    def _matches(s):
        if s.get("api_key_id") != api_key_id:
            return False
        if external_session_key is None:
            return s.get("external_session_key") is None
        return s.get("external_session_key") == external_session_key

    candidates = [s for s in sessions if _matches(s)]
    if not candidates:
        _log("close_session", api_key_id, None, "not_found", started)
        return _err("NOT_FOUND", "Session not found.")

    # Prefer active/cleared first, then others by updated_at
    def _rank(s):
        st = s.get("status")
        pri = 0
        if st in ("active", "cleared"):
            pri = 2
        elif st == "expired":
            pri = 1
        return (pri, s.get("updated_at") or "", s.get("created_at") or "")

    candidates.sort(key=_rank, reverse=True)
    session = candidates[0]
    sid = session.get("id")

    st = session.get("status")
    if st in ("closed", "expired"):
        _log("close_session", api_key_id, sid, "conflict", started)
        return _err("CONFLICT", f"Session is already {st}.")

    # Transition allowed: active/cleared -> closed
    if st not in ("active", "cleared"):
        _log("close_session", api_key_id, sid, "invalid_transition", started)
        return _err("INVALID_TRANSITION", f"Cannot transition session from {st} to closed.")

    # Reconcile thought_count invariant before closing (optional but keeps invariant)
    active_count = 0
    for t in thoughts:
        if t.get("session_id") == sid and t.get("status") == "active":
            active_count += 1
    if session.get("thought_count") != active_count:
        session["thought_count"] = active_count

    now = _now()
    session["status"] = "closed"
    session["updated_at"] = now
    _save("sessions.json", sessions)

    ev = {
        "id": "sev_" + uuid.uuid4().hex,
        "session_id": sid,
        "event_type": "session_closed",
        "event_payload": {"reason": reason} if reason is not None else None,
        "created_at": now,
        "updated_at": now
    }
    events.append(ev)
    _save("session_events.json", events)

    _log("close_session", api_key_id, sid, "ok", started)
    return {"session": session, "event": ev}

def reactivate_session(external_session_key=None, **_extra):
    import json, os, datetime, time, uuid

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0340000" if __import__("os").path.isdir("./environment_mix/0340000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    started = time.time()

    def _now_z():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _ensure_request_log():
        path = os.path.join(_DB, "request_logs.json")
        if not os.path.exists(path):
            _save("request_logs.json", [])
        return "request_logs.json"

    def _log(endpoint, api_key_id, session_id, http_status):
        try:
            logs = _load(_ensure_request_log())
            if not isinstance(logs, list):
                logs = []
            latency_ms = int(max(0.0, (time.time() - started) * 1000.0))
            logs.append({
                "id": "req_" + uuid.uuid4().hex,
                "endpoint": endpoint,
                "api_key_id": api_key_id,
                "session_id": session_id,
                "status": http_status,
                "latency_ms": latency_ms,
                "created_at": _now_z()
            })
            _save("request_logs.json", logs)
        except Exception:
            pass

    def _parse_dt(s):
        if s is None:
            return None
        if isinstance(s, datetime.datetime):
            return s
        if not isinstance(s, str):
            return None
        try:
            if s.endswith("Z"):
                s = s[:-1] + "+00:00"
            return datetime.datetime.fromisoformat(s)
        except Exception:
            return None

    def _rate_limit_check(api_key_row):
        rps = api_key_row.get("rate_limit_rps")
        if not isinstance(rps, (int, float)) or rps <= 0:
            return True
        logs = _load(_ensure_request_log())
        if not isinstance(logs, list):
            return True
        now = datetime.datetime.utcnow()
        cutoff = now - datetime.timedelta(seconds=1)
        c = 0
        for r in logs:
            if not isinstance(r, dict):
                continue
            if r.get("api_key_id") != api_key_row.get("id"):
                continue
            ts = _parse_dt(r.get("created_at"))
            if ts is None:
                continue
            if ts >= cutoff:
                c += 1
        return (c + 1) <= float(rps) + 1e-9

    def _resolve_session_to_reactivate(external_key):
        api_keys = _load("api_keys.json")
        sessions = _load("sessions.json")
        if not isinstance(api_keys, list):
            api_keys = []
        if not isinstance(sessions, list):
            sessions = []

        # Find all active keys
        active_keys = [k for k in api_keys if isinstance(k, dict) and k.get("status") == "active" and isinstance(k.get("id"), str) and k.get("id")]
        if not active_keys:
            return None, None, "UNAUTHORIZED", "No active API key context is available."

        # Filter sessions matching the request
        if external_key is not None:
            if not isinstance(external_key, str):
                return None, None, "VALIDATION_ERROR", "external_session_key must be a string."
            if len(external_key) < 1 or len(external_key) > 256:
                return None, None, "VALIDATION_ERROR", "external_session_key must be between 1 and 256 characters."
            matching = [s for s in sessions if isinstance(s, dict) and s.get("external_session_key") == external_key]
        else:
            # implicit session for a key: external_session_key is null and status in ('active','cleared')
            matching = [s for s in sessions if isinstance(s, dict) and s.get("external_session_key") is None and s.get("status") in ("active", "cleared")]

        if not matching:
            return None, None, "NOT_FOUND", "Session not found for the provided external_session_key." if external_key is not None else "No implicit session in active/cleared state was found."

        # Choose a session whose api_key is active. Prefer one already cleared (since this endpoint reactivates cleared->active).
        candidates = []
        key_by_id = {k.get("id"): k for k in active_keys}
        for s in matching:
            kid = s.get("api_key_id")
            if kid in key_by_id:
                candidates.append((key_by_id[kid], s))

        if not candidates:
            return None, None, "UNAUTHORIZED", "No authorized API key context exists for the requested session."

        def _rank(pair):
            s = pair[1]
            st = s.get("status")
            # prefer cleared first, then active, then others
            if st == "cleared":
                return 0
            if st == "active":
                return 1
            if st == "expired":
                return 2
            if st == "closed":
                return 3
            return 4

        candidates.sort(key=_rank)
        return candidates[0][0], candidates[0][1], None, None

    api_key_row, session_row, ecode, emsg = _resolve_session_to_reactivate(external_session_key)
    if ecode:
        _log("reactivate_session", api_key_row.get("id") if api_key_row else None, session_row.get("id") if session_row else None, 400 if ecode == "VALIDATION_ERROR" else (401 if ecode == "UNAUTHORIZED" else 404))
        return _err(ecode, emsg)

    if not _rate_limit_check(api_key_row):
        _log("reactivate_session", api_key_row.get("id"), session_row.get("id"), 429)
        return _err("RATE_LIMIT", "Rate limit exceeded for this API key.")

    st = session_row.get("status")
    if st in ("expired", "closed"):
        _log("reactivate_session", api_key_row.get("id"), session_row.get("id"), 409)
        return _err("CONFLICT", "Session cannot be reactivated because it is expired or closed.", current_status=st)

    if st == "active":
        # Idempotent: already active; return session as-is.
        _log("reactivate_session", api_key_row.get("id"), session_row.get("id"), 200)
        return {"data": session_row}

    if st != "cleared":
        _log("reactivate_session", api_key_row.get("id"), session_row.get("id"), 409)
        return _err("INVALID_TRANSITION", "Session can only be reactivated from 'cleared' to 'active'.", current_status=st, allowed_from=["cleared"])

    sessions = _load("sessions.json")
    if not isinstance(sessions, list):
        sessions = []

    # Mutate the matched row in the stored list
    sid = session_row.get("id")
    found = False
    now = _now_z()
    for s in sessions:
        if isinstance(s, dict) and s.get("id") == sid:
            s["status"] = "active"
            s["updated_at"] = now
            # Keep cleared_at as historical marker; do not restore thoughts.
            found = True
            session_row = s
            break

    if not found:
        _log("reactivate_session", api_key_row.get("id"), sid, 404)
        return _err("NOT_FOUND", "Session not found.")

    _save("sessions.json", sessions)

    # Append session event
    events = _load("session_events.json")
    if not isinstance(events, list):
        events = []
    evt_id = "ttk_evt_" + uuid.uuid4().hex
    events.append({
        "id": evt_id,
        "session_id": sid,
        "event_type": "session_created" if False else "session_created",  # placeholder overwritten below
        "event_payload": {"reactivated": True, "previous_status": "cleared"},
        "created_at": now,
        "updated_at": now
    })
    # Per schema, valid event types are fixed; no "session_reactivated". Record as "session_created" is wrong.
    # Use closest existing lifecycle event? None exists. So do not insert an invalid event row.
    # Remove the appended invalid row and persist only valid data.
    events.pop()

    _log("reactivate_session", api_key_row.get("id"), sid, 200)
    return {"data": session_row}

def get_session_events(event_type=None, limit=None, cursor=None, order=None, **_extra):
    import json, os, datetime, time, base64, uuid

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0340000" if __import__("os").path.isdir("./environment_mix/0340000") else "/app/database")
    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f: return json.load(f)
        except Exception: return []
    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f: json.dump(d, f, ensure_ascii=False, indent=2)
    def _err(code, msg, **x): return {"error": {"code": code, "message": msg, **x}}

    def _now_z():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _ensure_request_log():
        path = os.path.join(_DB, "request_logs.json")
        if not os.path.exists(path):
            _save("request_logs.json", [])
        return "request_logs.json"

    def _log(endpoint, api_key_id, session_id, status, started):
        try:
            logs = _load(_ensure_request_log())
            if not isinstance(logs, list):
                logs = []
            latency_ms = int(max(0.0, (time.time() - started) * 1000.0))
            logs.append({
                "id": "req_" + uuid.uuid4().hex,
                "endpoint": endpoint,
                "api_key_id": api_key_id,
                "session_id": session_id,
                "status": status,
                "latency_ms": latency_ms,
                "created_at": _now_z()
            })
            _save("request_logs.json", logs)
        except Exception:
            pass

    def _parse_dt(s):
        if s is None:
            return None
        if isinstance(s, datetime.datetime):
            return s
        if not isinstance(s, str):
            return None
        try:
            if s.endswith("Z"):
                s = s[:-1] + "+00:00"
            return datetime.datetime.fromisoformat(s)
        except Exception:
            return None

    def _b64d(s):
        raw = base64.urlsafe_b64decode((s + "===").encode("utf-8"))
        return raw.decode("utf-8")

    def _b64e(s):
        return base64.urlsafe_b64encode(s.encode("utf-8")).decode("utf-8").rstrip("=")

    started = time.time()

    # Validate inputs
    if event_type is not None:
        if not isinstance(event_type, str):
            _log("get_session_events", None, None, "error", started)
            return _err("VALIDATION_ERROR", "event_type must be a string.")
        if event_type not in ("think_appended", "thoughts_cleared", "session_created", "session_closed"):
            _log("get_session_events", None, None, "error", started)
            return _err("VALIDATION_ERROR", "Invalid event_type.", allowed=["think_appended", "thoughts_cleared", "session_created", "session_closed"])

    if limit is None:
        limit = 50
    if not isinstance(limit, int):
        _log("get_session_events", None, None, "error", started)
        return _err("VALIDATION_ERROR", "`limit` must be an integer.")
    if limit < 1 or limit > 200:
        _log("get_session_events", None, None, "error", started)
        return _err("VALIDATION_ERROR", "`limit` out of range.", minimum=1, maximum=200)

    if order is None:
        order = "desc"
    if not isinstance(order, str) or order not in ("asc", "desc"):
        _log("get_session_events", None, None, "error", started)
        return _err("VALIDATION_ERROR", "Invalid `order`.", allowed=["asc", "desc"])

    if cursor == "":
        cursor = None
    if cursor is not None and not isinstance(cursor, str):
        _log("get_session_events", None, None, "error", started)
        return _err("VALIDATION_ERROR", "`cursor` must be a string.")

    api_keys = _load("api_keys.json")
    sessions = _load("sessions.json")
    events = _load("session_events.json")

    if not isinstance(api_keys, list) or not isinstance(sessions, list) or not isinstance(events, list):
        _log("get_session_events", None, None, "error", started)
        return _err("UNAUTHORIZED", "No session/auth context is available.")

    # Resolve an ambient context that can serve the request: active key + a session under it.
    key = None
    for k in api_keys:
        if isinstance(k, dict) and k.get("status") == "active" and isinstance(k.get("id"), str):
            key = k
            break
    if key is None:
        _log("get_session_events", None, None, "error", started)
        return _err("UNAUTHORIZED", "No active API key context is available.")

    key_id = key["id"]
    candidate_sessions = [s for s in sessions if isinstance(s, dict) and s.get("api_key_id") == key_id]
    # Prefer active, then cleared, else any
    def _rank(s):
        st = s.get("status")
        if st == "active":
            return 0
        if st == "cleared":
            return 1
        return 2
    candidate_sessions.sort(key=_rank)
    session = candidate_sessions[0] if candidate_sessions else None
    if session is None or not isinstance(session.get("id"), str):
        _log("get_session_events", key_id, None, "error", started)
        return _err("UNAUTHORIZED", "No session/auth context is available.")

    session_id = session["id"]

    # Filter events by current session
    rows = [e for e in events if isinstance(e, dict) and e.get("session_id") == session_id]
    if event_type is not None:
        rows = [e for e in rows if e.get("event_type") == event_type]

    # Sort by created_at
    reverse = (order == "desc")
    def _k(e):
        dt = _parse_dt(e.get("created_at"))
        if dt is None:
            dt = datetime.datetime.min
        return (dt, e.get("id") or "")
    rows.sort(key=_k, reverse=reverse)

    # Cursor handling: accept foreign strings as "first page"; only error if our cursor decodes but doesn't match list.
    start_idx = 0
    next_cursor = None
    if cursor:
        parsed = None
        try:
            raw = _b64d(cursor)
            obj = json.loads(raw)
            if isinstance(obj, dict) and isinstance(obj.get("after_id"), str):
                parsed = obj
        except Exception:
            parsed = None

        if parsed is not None:
            after_id = parsed["after_id"]
            ids = [r.get("id") for r in rows]
            if after_id not in ids:
                _log("get_session_events", key_id, session_id, "error", started)
                return _err("VALIDATION_ERROR", "Invalid cursor.")
            start_idx = ids.index(after_id) + 1
        else:
            start_idx = 0

    page = rows[start_idx:start_idx + limit]
    if start_idx + limit < len(rows) and page:
        next_cursor = _b64e(json.dumps({"after_id": page[-1].get("id")}, ensure_ascii=False))

    resp = {
        "session_id": session_id,
        "data": page,
        "meta": {
            "total": len(rows),
            "limit": limit,
            "has_more": (start_idx + limit < len(rows)),
            "next_cursor": next_cursor
        }
    }
    _log("get_session_events", key_id, session_id, "ok", started)
    return resp

def revoke_api_key(reason=None, **_extra):
    import json, os, datetime, time

    _DB = __import__("os").environ.get("MCP_DB_DIR") or ("./environment_mix/0340000" if __import__("os").path.isdir("./environment_mix/0340000") else "/app/database")

    def _load(n):
        try:
            with open(os.path.join(_DB, n), encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return []

    def _save(n, d):
        with open(os.path.join(_DB, n), "w", encoding="utf-8") as f:
            json.dump(d, f, ensure_ascii=False, indent=2)

    def _err(code, msg, **x):
        return {"error": {"code": code, "message": msg, **x}}

    def _now_iso():
        return datetime.datetime.utcnow().replace(microsecond=0).isoformat() + "Z"

    def _parse_ts(s):
        if not s or not isinstance(s, str):
            return None
        try:
            if s.endswith("Z"):
                s2 = s[:-1]
                dt = datetime.datetime.fromisoformat(s2)
                return dt.replace(tzinfo=datetime.timezone.utc)
            return datetime.datetime.fromisoformat(s)
        except Exception:
            return None

    def _jsonable(x):
        try:
            json.dumps(x)
            return True
        except Exception:
            return False

    t0 = time.time()
    api_keys = _load("api_keys.json")

    # Validate inputs
    if reason is not None:
        if not isinstance(reason, str):
            return _err("VALIDATION_ERROR", "reason must be a string")
        if len(reason) > 1024:
            return _err("VALIDATION_ERROR", "reason must be at most 1024 characters")

    # Ambient authentication: pick a key that can satisfy prerequisites.
    # This endpoint requires "a key is presented"; in this local datastore model,
    # that maps to "there exists at least one api_keys row".
    # Additionally, revocation is only meaningful if it's active; but we must
    # return CONFLICT if already revoked.
    if not isinstance(api_keys, list) or len(api_keys) == 0:
        return _err("UNAUTHORIZED", "No API key presented")

    # Prefer an active key if any; else take a revoked one to return CONFLICT.
    key_row = None
    for r in api_keys:
        if isinstance(r, dict) and r.get("status") == "active":
            key_row = r
            break
    if key_row is None:
        for r in api_keys:
            if isinstance(r, dict) and r.get("status") == "revoked":
                key_row = r
                break
    if key_row is None:
        return _err("UNAUTHORIZED", "No API key presented")

    # Enforce lifecycle transition
    if key_row.get("status") == "revoked":
        return _err("CONFLICT", "API key is already revoked")

    if key_row.get("status") != "active":
        return _err("INVALID_TRANSITION", "API key is not in a revocable state", current_status=key_row.get("status"))

    # Transition to revoked
    now = _now_iso()
    key_row["status"] = "revoked"
    key_row["updated_at"] = now
    key_row["revoked_at"] = now

    # Store reason where supported: schema doesn't include it; add only if safe.
    if reason is not None:
        # Maintain forward-compatible metadata without breaking existing fields.
        meta = key_row.get("metadata")
        if meta is None:
            meta = {}
        if not isinstance(meta, dict):
            # If existing metadata is non-dict, refuse to overwrite silently.
            return _err("CONFLICT", "Cannot record revocation reason due to incompatible key metadata")
        meta["revocation_reason"] = reason
        meta["revocation_reason_recorded_at"] = now
        if _jsonable(meta):
            key_row["metadata"] = meta
        else:
            return _err("CONFLICT", "Cannot record revocation reason due to unserializable metadata")

    # Persist
    _save("api_keys.json", api_keys)

    latency_ms = int((time.time() - t0) * 1000)

    return {
        "api_key": {
            "id": key_row.get("id"),
            "key_prefix": key_row.get("key_prefix"),
            "label": key_row.get("label"),
            "status": key_row.get("status"),
            "revoked_at": key_row.get("revoked_at"),
            "updated_at": key_row.get("updated_at"),
        },
        "meta": {
            "latency_ms": latency_ms,
            "timestamp": now,
        },
    }
